insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('d920c06b-178a-415c-8e11-cac32c17587e', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$inleiding: dalende werkloosheid in de VS zonder hoge loonstijging en inflatie$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context1.png$$,
   $$In de periode 2010 tot en met 2014 groeide het reële bruto binnenlands product (bbp) in de VS en daarmee de vraag naar arbeid. De werkloosheid daalde in deze periode van 9,8% naar 5,7% van de beroepsbevolking. De daling van de werkloosheid zou volgens de economen hebben moeten leiden tot hogere lonen en daarmee tot inflatie. Opvallend is echter dat in dezelfde periode de stijging van de lonen en de inflatie beperkt bleef.$$, 'inline'),
  ('fa9dac9a-4a18-4fcd-a075-5d4d3c81eba4', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$stelling Janets: arbeidsaanbod reageert sterker op loonstijging$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context2.png$$,
   $$Econome Janets stelt: “De combinatie van lage werkloosheid en lage inflatie werd mede veroorzaakt doordat het arbeidsaanbod sterker is gaan reageren op een stijging van de lonen. Als gevolg hiervan is de inflatie minder hoog dan verwacht.”$$, 'inline'),
  ('e1555e2d-1ed6-4ad7-8d89-f3e22f8b742c', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$loonelasticiteit van het arbeidsaanbod 2010-2014$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context3.png$$,
   $$De loonelasticiteit van het arbeidsaanbod blijkt in de periode 2010-2014 iets hoger te zijn geweest dan in de periode 2005-2009. Voor de loonelasticiteit van het arbeidsaanbod geldt de volgende formule:$$, 'inline'),
  ('9f16021d-61f6-4e99-a491-e25d8609edd1', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$formule loonelasticiteit van het arbeidsaanbod$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context4.png$$,
   $$Eₗₐ = procentuele verandering arbeidsaanbod / procentuele verandering loon$$, 'inline'),
  ('a6efad79-f530-4a26-bbe5-ac8e82f5cd31', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$tabel 1: arbeidsmarktgegevens in de VS$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context5.png$$,
   $$Tabel 1 arbeidsmarktgegevens in de VS
| beroepsbevolking* | werkgelegenheid* | werkloosheid* | werkloosheidspercentage
1-1-2010 | 153.484 | 138.438 | 15.046 | 9,8
1-1-2015 | 157.180 | 148.201 | 8.979 | 5,7
* x 1.000 arbeidsjaren$$, 'inline'),
  ('453a030f-e5a5-47e0-a15f-6978d7eff0a7', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$tabel 2: procentuele groei van het gemiddelde loon in de VS$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context6.png$$,
   $$Tabel 2 procentuele groei van het gemiddelde loon in de VS
jaar | 2010 | 2011 | 2012 | 2013 | 2014
jaarlijkse groei | 2,36 | 3,13 | 3,12 | 1,28 | 3,55$$, 'inline'),
  ('42067025-6305-487b-9130-137675b59db4', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$Janets: renteverhoging via kapitaalrekening en wisselkoers$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context7.png$$,
   $$Janets verwacht dat in de periode vanaf 2015 de groei van het arbeidsaanbod zal afnemen. Bij aanhoudende groei van het reële bbp kan volgens haar de inflatie dan weer hoger uitvallen dan wenselijk. Het lijkt haar raadzaam dat de rente wordt verhoogd, omdat daarmee op termijn de groei van het bbp kan worden beperkt: “Een renteverhoging heeft via de kapitaalrekening van de betalingsbalans effect op de wisselkoers van de US dollar, en daarmee op de lopende rekening. Dit kan leiden tot de gewenste afname van de groei van het bbp.”$$, 'inline'),
  ('57c8def6-8622-4807-a524-db7c947e23cd', '994d0911-6606-4a31-a4eb-03d3d36aaed0', $$stelling Paulman: stijging arbeidsproductiviteit$$,
   $$economie-vwo-2019-i-rek-in-het-arbeidsaanbod-context8.png$$,
   $$Econoom Kurt Paulman meent dat de daling van de groei van het arbeidsaanbod niet tot veel meer inflatie hoeft te leiden. Paulman stelt: “Het feit dat in de periode 2010 tot en met 2014 de inflatie jaarlijks lager uitviel dan de groei van het gemiddelde loon, kan namelijk ook verklaard worden uit de stijging van de arbeidsproductiviteit.”$$, 'inline'),
  ('13d193de-3a3b-4342-b271-acab46369e6a', 'b3406c08-5fdd-4def-881b-ab3badde70e4', $$inleiding: langdurige laagconjunctuur; beleidsrente op de zero lower bound; schulden huishoudens$$,
   $$economie-vwo-2019-i-als-het-geld-niet-wil-rollen-context1.png$$,
   $$De economie van een land is als gevolg van een crisis in het bankwezen terechtgekomen in een langdurige laagconjunctuur met een inflatie dicht bij nul procent. Een econoom maakt een analyse waarbij hij een verklaring wil geven voor het uitblijven van economisch herstel. Hij wijst op een tweetal zaken die van belang zijn voor het begrijpen van de economische situatie:
− De Centrale Bank (CB) bepaalt via haar beleidsrente de marktrente. De gewenste marktrente hangt af van de verwachte inflatie. De CB streeft naar een inflatie van twee procent en zou in de huidige situatie voor een negatieve beleidsrente willen kiezen. Met het oog op de zero lower bound is de huidige beleidsrente op nul procent gesteld.
− Schulden van huishoudens zijn sinds de crisis sterk toegenomen als gevolg van werkloosheid.$$, 'inline'),
  ('e7060a22-afc9-48ad-ac3a-7607d1022471', 'b3406c08-5fdd-4def-881b-ab3badde70e4', $$geaggregeerde vraag stijgt nauwelijks bij dalend prijspeil$$,
   $$economie-vwo-2019-i-als-het-geld-niet-wil-rollen-context2.png$$,
   $$De econoom concludeert dat de geaggregeerde vraag nauwelijks stijgt als het prijspeil daalt. Dat is het resultaat van een aantal verbanden die deels tegen elkaar inwerken. De econoom illustreert deze verbanden in figuur 1.$$, 'inline'),
  ('c102b17f-38a4-43bc-aed9-de0ebd26f7fc', 'b3406c08-5fdd-4def-881b-ab3badde70e4', $$figuur 1: verbanden tussen prijspeil en geaggregeerde vraag$$,
   $$economie-vwo-2019-i-als-het-geld-niet-wil-rollen-context3.png$$,
   $$Figuur 1 verbanden tussen prijspeil en geaggregeerde vraag
Schema: ''prijspeil'' wijst via drie tussenstappen (''financiële bezittingen'', ''reële rente'', ''schulden'') naar ''geaggregeerde vraag''.$$, 'inline'),
  ('cddd4a2b-0923-4265-9c62-cc714f447b7e', 'b3406c08-5fdd-4def-881b-ab3badde70e4', $$verdere analyse met figuur 2$$,
   $$economie-vwo-2019-i-als-het-geld-niet-wil-rollen-context4.png$$,
   $$De econoom maakt in zijn verdere analyse van de te verwachten economische ontwikkelingen gebruik van figuur 2, met de geaggregeerde vraag- en aanbodlijnen voor de korte en lange termijn.$$, 'inline'),
  ('fc2a46e3-d17f-44dc-8b64-26d44495d4e8', 'b3406c08-5fdd-4def-881b-ab3badde70e4', $$figuur 2: geaggregeerde vraag en aanbod, korte en lange termijn$$,
   $$economie-vwo-2019-i-als-het-geld-niet-wil-rollen-context5.png$$,
   $$Figuur 2 geaggregeerde vraag en aanbod, korte- en lange termijn
Grafiek met prijspeil (verticaal) en reëel bbp (horizontaal): een steile, dalende GV-lijn; een verticale GAₗₜ-lijn rechts van het snijpunt; een horizontale GAₖₜ-lijn. GV snijdt GAₖₜ links van GAₗₜ.
GV = geaggregeerde vraag
GAₗₜ = geaggregeerd aanbod op de lange termijn
GAₖₜ = geaggregeerd aanbod op de korte termijn$$, 'inline'),
  ('21c3364b-cf0d-424a-be6e-fa395da2773d', 'b3406c08-5fdd-4def-881b-ab3badde70e4', $$toelichting GAlt- en GAkt-lijn$$,
   $$economie-vwo-2019-i-als-het-geld-niet-wil-rollen-context6.png$$,
   $$De econoom licht toe dat de GAₗₜ-lijn de productiecapaciteit van het land weergeeft. De GAₖₜ-lijn wordt bepaald door de omvang van de feitelijke productie, gegeven de ervaring dat er op korte termijn sprake is van starheid van lonen en prijzen.$$, 'inline'),
  ('6f96c0e4-3a58-4e44-ab29-2087895eaa0a', '529111c9-9d42-4a81-987f-3730ec811563', $$inleiding: private business schools BSA en BSB en publieke instellingen; vraagfuncties$$,
   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-context1.png$$,
   $$In een land binnen de eurozone zijn twee private instellingen voor hoger beroepsonderwijs actief: business school A (BSA) en business school B (BSB). Daarnaast bestaan er publieke instellingen voor hoger onderwijs, gefinancierd door de overheid. Studenten aan de publieke onderwijsinstellingen hoeven vooralsnog geen lesgeld of collegegeld te betalen en de studieduur is onbeperkt. BSA en BSB streven elk op korte termijn naar een zo groot mogelijke omzet. Voor het lopende collegejaar is het collegegeld van BSA € 15.000 en van BSB € 20.000 per student. De directies gaan uit van de volgende functies:
− Qva = −0,2 Pa + 0,1 Pb + 0,05 Po + 4.500
− Qvb = 0,25 Pa − 0,3 Pb + 0,04 Po + 8.000$$, 'inline'),
  ('c8a943b8-fcb3-40cf-9296-16e9085353c7', '529111c9-9d42-4a81-987f-3730ec811563', $$verklaring symbolen in de vraagfuncties$$,
   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-context2.png$$,
   $$Qva = aantal studenten van BSA Qvb = aantal studenten van BSB Pa = collegegeld per jaar van BSA Pb = collegegeld per jaar van BSB Po = collegegeld publieke onderwijsinstellingen (vooralsnog: Po = nul)$$, 'inline'),
  ('85d7394e-b75d-4e39-850c-bd19008706e7', '529111c9-9d42-4a81-987f-3730ec811563', $$BSA en BSB hebben alleen inkomsten uit collegegeld$$,
   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-context3.png$$,
   $$BSA en BSB hebben geen andere inkomsten dan collegegeld.$$, 'inline'),
  ('8886a4a4-b329-4a44-9efe-7a1541490f2a', '529111c9-9d42-4a81-987f-3730ec811563', $$overweging collegegeld met 10% te verhogen$$,
   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-context4.png$$,
   $$Voor het komende collegejaar overwegen de directies van BSA en BSB onafhankelijk van elkaar om de collegegelden te verhogen met 10%. Op basis van bovenstaande functies is onderstaande pay-off matrix opgesteld.$$, 'inline'),
  ('d671dc64-598a-4d69-b1bf-310c1fe7192b', '529111c9-9d42-4a81-987f-3730ec811563', $$matrix 1: procentuele veranderingen van de totale opbrengsten aan collegegelden$$,
   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-context5.png$$,
   $$Matrix 1 procentuele veranderingen van de totale opbrengsten aan collegegelden ten opzichte van de huidige situatie
| BSB houdt collegegeld gelijk | BSB verhoogt collegegeld met 10%
BSA houdt collegegeld gelijk | (0, 0) | (+ 5,71, − 1,48)
BSA verhoogt collegegeld met 10% | (+ 0,57, + 6,52) | (+ 6,86, + 5,70)$$, 'inline'),
  ('631c2df6-8d59-465e-9d2f-484474e5f78a', '529111c9-9d42-4a81-987f-3730ec811563', $$minister: collegegeld bij publieke instellingen; solidariteit en moral hazard$$,
   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-context6.png$$,
   $$De minister van Onderwijs overweegt collegegeld in te voeren voor studenten aan publieke instellingen voor hoger onderwijs. Hij stelt:
− “De huidige financiering van het publieke onderwijs is een vorm van verplichte solidariteit binnen de samenleving.
− Aangezien bij publieke onderwijsinstellingen nu nog geen collegegeld hoeft te worden betaald kan daar bij studenten moral hazard optreden.
− Hierdoor kan het draagvlak voor deze solidariteit worden aangetast.”$$, 'inline'),
  ('ecf73fe3-32c2-4505-84ec-0eb099a089f3', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', $$inleiding: Pesthan beperkt importen met heffingen en quota (infant industry)$$,
   $$economie-vwo-2019-i-protectie-een-lapmiddel-context1.png$$,
   $$De overheid van het ontwikkelingsland Pesthan gebruikte van 1995 tot 2015 het infant industry argument om de importen te beperken. Zij verhoogde daartoe de importheffingen en stelde importquota in. De nationale munt, de pesto, is vrij inwisselbaar.$$, 'inline'),
  ('38f67b40-5810-4e0d-bad3-d2d06e0bff40', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', $$onderzoek Economisch Adviesorgaan; tabel 1: macro-economische waarden van Pesthan$$,
   $$economie-vwo-2019-i-protectie-een-lapmiddel-context2.png$$,
   $$In 2015 krijgt het Economisch Adviesorgaan (EA) van de nieuwe regering de opdracht om te onderzoeken of vermindering van de belemmeringen op importen mogelijk gunstig kan zijn voor gezinnen en bedrijven in het land. Het EA presenteert informatie van Pesthan in tabel 1 en van vergelijkbare ontwikkelingslanden in grafiek 1 en 2.
Tabel 1 macro-economische waarden van Pesthan in miljard pesto
| | 1995 | 2015
C | particuliere consumptie | 120 | 140
Ibruto | bruto-bedrijfsinvesteringen | 12,5 | 15
Obruto | bruto-overheidsbestedingen | 56 | 57
E | exportwaarde goederen en diensten | 18 | 22,5
M | importwaarde goederen en diensten | 20 | 25$$, 'inline'),
  ('817bff2b-c2e9-4755-ab8e-0f08aa5e2f2c', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', $$formule internationale handelsquote$$,
   $$economie-vwo-2019-i-protectie-een-lapmiddel-context3.png$$,
   $$Een indicator voor de openheid van de economie wat betreft de internationale handel is de internationale handelsquote, berekend volgens onderstaande formule. In het jaar 1995 bedroeg deze 0,20.
Internationale handelsquote = (egd + mgd) / bbp
Waarbij: egd = exportwaarde goederen en diensten
mgd = importwaarde goederen en diensten
bbp = bruto binnenlands product$$, 'inline'),
  ('2bb671a8-97aa-46f8-bf77-428ebf7f1bc9', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', $$EA: exportstijging mogelijk door waardeverandering van de pesto$$,
   $$economie-vwo-2019-i-protectie-een-lapmiddel-context4.png$$,
   $$Het EA stelt: “De stijging van de exportwaarde van goederen en diensten is niet alleen een gevolg van het protectionistische beleid, gericht op versterking van opkomende bedrijven. Het kan ook zijn veroorzaakt door een waardeverandering van de pesto. Deze waardeverandering kan ook hebben bijgedragen aan de stijging van het binnenlandse prijsniveau.”$$, 'inline'),
  ('628777cc-29a4-4ee8-a344-09a3ab2dfb26', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', $$grafiek 1: handelsquote en bbp-groei; grafiek 2: handelsquote en Gini-coëfficiënt$$,
   $$economie-vwo-2019-i-protectie-een-lapmiddel-context5.png$$,
   $$Grafiek 1 verandering internationale handelsquote en bbp bij vergelijkbare ontwikkelingslanden
Stijgende rechte lijn: gem. jaarlijkse verandering handelsquote (%) van −4 tot 6 (horizontaal) tegen gem. jaarlijkse groei bbp (verticaal): bij −4 ongeveer 0,4; bij 0 ongeveer 2,0; bij 6 ongeveer 4,4.
Grafiek 2 verandering internationale handelsquote en Gini-coëfficiënt bij vergelijkbare ontwikkelingslanden
Dalende rechte lijn: gem. jaarlijkse verandering handelsquote (%) (horizontaal) tegen gem. jaarlijkse verandering Gini-coëfficiënt (verticaal): bij ongeveer −2,5 ongeveer +0,4; bij 0 ongeveer −0,6; bij 4 ongeveer −2,2.$$, 'inline'),
  ('837cfc35-d37c-4389-9945-662034bcab44', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', $$advies EA: meer vrijhandel; i. lonen, ii. inkomensverdeling$$,
   $$economie-vwo-2019-i-protectie-een-lapmiddel-context6.png$$,
   $$Op basis van de informatie in grafieken 1 en 2 adviseert het EA om meer vrijhandel toe te laten. Het EA stelt dat hierdoor: i. de arbeidsmarkt verkrapt zodat de lonen in het land verder kunnen stijgen en ii. de inkomensverdeling gelijker wordt.$$, 'inline'),
  ('6d1f86dc-2d79-4414-8b31-92411300caea', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$inleiding: heterogeen duopolie WOP en OBX in regio's Oost en West$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context1.png$$,
   $$Twee bedrijven, Westeropslag (WOP) en Oostbox (OBX), verhuren containeropslagruimte aan particulieren in een land. Er is sprake van een heterogeen duopolie. Het land bestaat uit de regio’s Oost en West. De afzet van de bedrijven wordt gemeten naar het aantal vierkante meter opslagruimte dat ze verhuren. OBX realiseert zestig procent van de totale eigen afzet in regio Oost, WOP 60% van de totale eigen afzet in regio West.$$, 'inline'),
  ('7844ddb9-1c02-43d0-bf78-c4a97de5fe4b', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$WOP overweegt prijsverhoging van 10%; uitgangssituatie 36.500 m²$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context2.png$$,
   $$Met het oog op stijging van de kosten overweegt WOP om de verkoopprijs met tien procent te verhogen. WOP gaat ervan uit dat ook OBX een dergelijke stap overweegt. WOP onderzoekt de marktverhoudingen en de effecten op de omzet van een verandering van de prijs (matrix 1). In de uitgangssituatie verhuurt WOP 36.500 m² opslagruimte.$$, 'inline'),
  ('9f05a9c3-c404-46df-8134-4373a0d858c4', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$matrix 1: prijscombinaties en verwachte omzet$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context3.png$$,
   $$Matrix 1 prijscombinaties en verwachte omzet (× 1.000 euro’s)
| | OBX |
| P* | 5,30 | 5,83
WOP | 5 | 182,5; 146,3 | 195,8; 136,2
| 5,50 | 173,3; 156,9 | 187,8; 147,9
* prijzen per m² opslagruimte$$, 'inline'),
  ('77624280-3a5a-405c-94e7-e55a1a9b3ad2', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$voorstel prijsafspraak en tegenvoorstel van OBX per regio$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context4.png$$,
   $$WOP stelt aan OBX voor om een prijsafspraak te maken waarbij beide de prijs verhogen met 10%. OBX doet een tegenvoorstel om per regio een prijsafspraak te maken. OBX zou in regio West de prijs verhogen met 100% waardoor WOP hier als monopolist kan optreden. Door eenzelfde prijsverhoging van WOP in regio Oost zal OBX daar ook geen concurrentie meer ondervinden.$$, 'inline'),
  ('23fcd379-8013-45b4-bfa2-6999d32d70bd', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$analyse WOP: prijs van 6 euro bij voorstel OBX$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context5.png$$,
   $$WOP wil alleen akkoord gaan met het voorstel van OBX als de verwachte totale omzet van WOP daarbij minstens gelijk is aan die bij het eigen voorstel. Een medewerker van WOP stelt op basis van een analyse: “Om bij het voorstel van OBX eenzelfde omzet te behalen als bij ons eigen voorstel, zal WOP een prijs per vierkante meter moeten rekenen van 6 euro. Er is dan van uitgegaan dat de totale afzet in regio West hierbij daalt met 5% ten opzichte van de uitgangssituatie.”$$, 'inline'),
  ('277b6f32-d8f2-4511-869b-dd69a74f0ec1', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$kartel; onderzoek door de mededingingsautoriteit LMA$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context6.png$$,
   $$Uiteindelijk gaat WOP akkoord met het voorstel van OBX. Na enige tijd krijgt de landelijke mededingingsautoriteit (LMA) echter het vermoeden van het bestaan van het kartel en start een onderzoek. De ervaring leert dat de LMA in drie van de vier keer dat ze een onderzoek uitvoert, zonder voorafgaande melding een kartelafspraak kan aantonen. De website van de LMA vermeldt de boeteregeling voor het deelnemen aan kartels:$$, 'inline'),
  ('126b6231-8557-47b6-b68f-bf9418891c10', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$boeteregeling van de LMA$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context7.png$$,
   $$− Als de LMA in staat is het kartel aan te tonen, krijgt elk deelnemend bedrijf dat niet heeft gemeld een boete gelijk aan vier keer de extra omzet als gevolg van het kartel.
− Een bedrijf kan ook zelf een kartelafspraak melden. Een bedrijf dat dit als eerste doet, krijgt geen boete opgelegd.
− Ieder volgend deelnemend bedrijf dat een melding maakt voordat de LMA het kartel heeft aangetoond, krijgt een boete gelijk aan de extra omzet als gevolg van het kartel.$$, 'inline'),
  ('03333036-80b9-4676-8b93-20b24a3f5587', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$directielid tekent spelboom$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context8.png$$,
   $$Op basis van deze boeteregeling tekent een directielid van WOP onderstaande spelboom. Zij realiseert zich dat OBX een gelijksoortige spelboom kan opstellen, waarin geldt dat OBX als eerste zijn keuze bepaalt.$$, 'inline'),
  ('1fcdd3f5-7c58-43d3-89a3-7431b443087a', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$figuur 1: spelboom met verwachte waarden van boetes$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context9.png$$,
   $$Figuur 1 spelboom met verwachte waarden van boetes als percentage van de extra omzet
WOP kiest eerst (melden / niet melden), daarna OBX (melden / niet melden). Uitkomsten (WOP; OBX):
WOP melden, OBX melden: 0; 100
WOP melden, OBX niet melden: 0; 400
WOP niet melden, OBX melden: 400; 0
WOP niet melden, OBX niet melden: 300; 300$$, 'inline'),
  ('d93c68fb-8482-45fd-ac9f-e13d233a619e', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$notitie ExamenCentraal: vraag 23 altijd 2 scorepunten (vraagstelling niet eenduidig)$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context10.png$$,
   $$Op pagina 11 van het correctievoorschrift, bij vraag 23 moeten altijd 2 scorepunten worden toegekend, ongeacht of er wel of geen antwoord gegeven is, en ongeacht het gegeven antwoord.
Toelichting: De vraagstelling is niet eenduidig. Het is niet helder wat er toegelicht dient te worden.$$, 'inline'),
  ('f6072b74-9502-4b07-aa01-4267fc2b6285', '2c229bde-2352-44da-bb3d-82a4a33183c1', $$directrice: zo snel mogelijk melden gegeven het Nash-evenwicht$$,
   $$economie-vwo-2019-i-wie-krijgt-de-opslag-context11.png$$,
   $$De directrice van WOP stelt: “Gegeven het Nash-evenwicht in de spelboom, stel ik voor om zo snel mogelijk te melden. Anders is straks de stijging van onze omzet geheel tenietgedaan door de boete van de LMA.”$$, 'inline'),
  ('efcbd12a-5f4b-45df-8602-232c8b2f0f23', 'c972b0d0-4d52-4716-a94d-ab31ff3e771a', $$inleiding: oudedagsvoorziening via omslagstelsel; bruto-verdienpotentieel en financieel vermogen$$,
   $$economie-vwo-2019-i-een-welverdiende-oude-dag-context1.png$$,
   $$In een land bestaat een oudedagsvoorziening, gebaseerd op het omslagstelsel. Er is geen verplichte eigen pensioenopbouw. Een politicus pleit voor een verlaging van de bestaande uitkering. Een econoom onderzoekt de gevolgen van dit plan. Hij schetst daartoe een modelmatige weergave van de financiële positie van een werknemer tijdens diens werkzame periode en in de periode daarna (zie figuur 1). De econoom stelt het bruto-verdienpotentieel van een werknemer gelijk aan het totale arbeidsinkomen dat deze vanaf een bepaald moment nog zal verwerven tot aan diens pensionering. In figuur 1 schetst de econoom ook het verloop van het financieel vermogen van een werknemer, vanaf het betreden van de arbeidsmarkt tot het overlijden. Voor opbouw van dit financieel vermogen wordt een deel van het bruto-verdienpotentieel bestemd.$$, 'inline'),
  ('525f05c8-1c6c-4437-acd1-4197361ea7a9', 'c972b0d0-4d52-4716-a94d-ab31ff3e771a', $$figuur 1: model van de levensloop van een werknemer; uitgangspunten van het model$$,
   $$economie-vwo-2019-i-een-welverdiende-oude-dag-context2.png$$,
   $$Figuur 1 model van de levensloop van een werknemer
Grafiek (euro''s tegen de tijd van betreden arbeidsmarkt via pensionering tot overlijden): het bruto-verdienpotentieel daalt lineair van punt a (4 miljoen) bij het betreden van de arbeidsmarkt tot 0 bij pensionering; het financieel vermogen stijgt lineair van punt c (0) bij het betreden van de arbeidsmarkt tot punt b (0,6 miljoen) bij pensionering en daalt daarna lineair tot 0 bij overlijden.
De uitgangspunten van de econoom bij het model zijn:
- De inflatie en de rente bedragen beide 0%.
- Het loonpeil blijft onveranderd.
- Heffingen op het inkomen (inclusief premies voor de oudedagsvoorziening) bedragen steeds 30% van het inkomen.
- Na pensionering wordt geen inkomen meer verdiend.
De econoom licht toe dat de punten a en c in dit model ook hoger of lager getekend zouden kunnen worden. Het financieel vermogen zou bij het betreden van de arbeidsmarkt negatief kunnen zijn, gekoppeld aan een hoger verdienpotentieel.$$, 'inline'),
  ('ace7e8e4-60d5-4502-8f52-7b6cf9aad6e5', 'c972b0d0-4d52-4716-a94d-ab31ff3e771a', $$positie punt b en tijdsvoorkeur$$,
   $$economie-vwo-2019-i-een-welverdiende-oude-dag-context3.png$$,
   $$De positie van punt b wordt onder andere bepaald door de tijdsvoorkeur van een werknemer gedurende diens werkzame leven.$$, 'inline'),
  ('b1d42733-5f39-4e01-be36-7db12c0d4225', 'c972b0d0-4d52-4716-a94d-ab31ff3e771a', $$vast deel van het inkomen wordt geconsumeerd$$,
   $$economie-vwo-2019-i-een-welverdiende-oude-dag-context4.png$$,
   $$De econoom gaat er in figuur 1 van uit dat een vast deel van het inkomen wordt geconsumeerd.$$, 'inline'),
  ('0b35f22d-e229-4abe-8a67-d669ecd7ebcd', 'c972b0d0-4d52-4716-a94d-ab31ff3e771a', $$lagere uitkering oudedagsvoorziening: punt b hoger$$,
   $$economie-vwo-2019-i-een-welverdiende-oude-dag-context5.png$$,
   $$De econoom meent dat door verlaging van de uitkering van de oudedagsvoorziening figuur 1 zal veranderen. Hij beweert dat als wordt uitgegaan van een lagere uitkering punt b hoger zal komen te liggen.$$, 'inline'),
  ('800fe80c-5512-4441-974a-5d8f8ed2ceed', 'c972b0d0-4d52-4716-a94d-ab31ff3e771a', $$beleggingsadviseur: jongeren aandelen, ouderen obligaties of betaalrekening$$,
   $$economie-vwo-2019-i-een-welverdiende-oude-dag-context6.png$$,
   $$De politicus pleit ervoor dat werknemers zelf via beleggingen een aanvullende oudedagsvoorziening regelen. Een beleggingsadviseur stelt dat in dat geval jonge werknemers vooral zouden moeten kiezen voor het hoge rendement van aandelen, ondanks het relatief hoge koersrisico. Naarmate de pensioenleeftijd dichterbij komt gaat volgens hem dit risico zwaarder wegen en hij raadt de dan inmiddels oudere werknemers aan om gaandeweg over te stappen op obligaties, of zelfs om een deel van het vermogen op een betaalrekening te houden.$$, 'inline');

