   $$economie-vwo-2019-i-markt-voor-hoger-onderwijs-vraag12.png$$, $$2p 12 Geef de berekening van de waarde van 0,57% linksonder in de matrix op basis van de beide gegeven functies. (altijd 2 punten ivm aanvulling correctie)$$, array['6f96c0e4-3a58-4e44-ab29-2087895eaa0a', 'c8a943b8-fcb3-40cf-9296-16e9085353c7', '85d7394e-b75d-4e39-850c-bd19008706e7', '8886a4a4-b329-4a44-9efe-7a1541490f2a', 'd671dc64-598a-4d69-b1bf-310c1fe7192b']::uuid[]),
