  ('da3c445e-8d99-4e92-9747-53539ab4955c', 'bdc41cf4-4c8c-447e-91ca-e004c1a6d181', 16,
   '[{"domain": "Welvaart en groei", "subdomain": "Structurele groei"}]'::jsonb,
   '["infant industry", "protectionisme", "schaalvoordelen", "leereffecten", "concurrentiepositie"]'::jsonb,
